function e(mixed $value): string { return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
function number(mixed $n): string { return number_format((int)$n); }
function duration(mixed $n): string { $n=(int)$n;return $n>=3600?sprintf('%dh %02dm',intdiv($n,3600),intdiv($n%3600,60)):sprintf('%dm %02ds',intdiv($n,60),$n%60); }
function map_title(string $map): string { return str_replace('_',' ',preg_replace('/\.map$/','',basename($map))); }
function stamp(string $date): string { return gmdate('d M Y · H:i',strtotime($date.' UTC')).' UTC'; }
function page_header(string $active,?array $me=null): void {
    // Keep application links functional when the host ignores .htaccess routing.
    ob_start(function(string $html): string {
        return preg_replace_callback('~\b(href|action)="(/[^" ]*)"~', function(array $match): string {
            $path=$match[2];
            if ($path==='/' || str_starts_with($path,'/#') || str_starts_with($path,'/assets/') || str_starts_with($path,'/index.php') || str_starts_with($path,'//')) return $match[0];
            return $match[1].'="'.route_url($path).'"';
        },$html);
    });
    $titles=['connect'=>'Connect your game','community'=>'Community','creations'=>'Creations','features'=>'Features','network'=>'Network services','api-browser'=>'API browser','home'=>'A new front for a classic RTS','servers'=>'Server directory','leaderboard'=>'Leaderboards','statistics'=>'Community statistics','downloads'=>'Downloads','account'=>'Your account','guide'=>'Field guide','profile'=>'Player profile','credits'=>'Credits & project history'];
    ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="zod-enhanced. A classic real-time strategy game, rebuilt for modern machines. Find servers, track your battles, and join the community."><meta name="theme-color" content="#1b2227"><title><?=e($titles[$active]??'zod-enhanced')?> — zod-enhanced</title><link rel="icon" type="image/svg+xml" href="/assets/favicon.svg?v=z-reliability-19"><link rel="stylesheet" href="/assets/site.css?v=z-reliability-20"><script src="/assets/site.js?v=z-reliability-19" defer></script></head><body data-api-prefix="<?=env_value('ZOD_CLEAN_URLS')==='1'?'':'/index.php'?>"><a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="shell header-inner"><a class="brand" href="/" aria-label="zod-enhanced home"><span class="brand-mark">Z</span><span>zod-enhanced<span class="brand-sub">ZOD ENGINE ENHANCED</span></span></a><button class="nav-toggle" aria-expanded="false" aria-controls="main-nav">Menu <span>☰</span></button><nav id="main-nav" aria-label="Main navigation"><?php foreach(['home'=>'Overview','features'=>'Features','network'=>'Network','servers'=>'Servers','community'=>'Community','creations'=>'Creations','leaderboard'=>'Leaderboard','downloads'=>'Downloads'] as $key=>$label):?><a href="<?=$key==='home'?'/':'/'.$key?>" <?=$active===$key?'aria-current="page"':''?>><?=$label?></a><?php endforeach?></nav><?php if($me):?><a href="/my-servers" class="text-link">My servers</a><a href="/reports" class="text-link">Report</a><?php if((new ZodService())->isOperator()):?><a href="/admin" class="text-link">Moderate</a><?php endif;endif?><a class="account-link" href="/account"><span class="account-dot"></span><?=e($me['username']??'Sign in')?> <span aria-hidden="true">↗</span></a></div></header><main id="main" tabindex="-1">
    <?php
}
