function title_block(string $eyebrow,string $title,string $description): void { ?><div class="page-heading"><span class="eyebrow"><?=e($eyebrow)?></span><h1><?=e($title)?></h1><p><?=e($description)?></p></div><?php }
function empty_state(string $title,string $description,string $link='/guide',string $label='Read the field guide'): void { ?><div class="empty-state"><span class="empty-cross" aria-hidden="true">＋</span><h3><?=e($title)?></h3><p><?=e($description)?></p><a class="text-link" href="<?=e($link)?>"><?=e($label)?> </a></div><?php }
function server_table(array $servers): void {
    if (!$servers) {empty_state('The battlefield is quiet.','No public servers are announcing right now. Host a server, or come back when a new lobby opens.','/guide#hosting','Learn to host');return;}
    ?><div class="table-scroll"><table class="server-table"><thead><tr><th>Server / map</th><th>Status</th><th>Players</th><th>Address</th><th><span class="sr-only">Join server</span></th></tr></thead><tbody><?php foreach($servers as $s):$full=isset($s['player_slots'])?$s['player_slots']===0:$s['players']>=$s['capacity'];?><tr data-server="<?=e($s['id'])?>" data-region="<?=e($s['region']??'Unspecified')?>" data-mode="<?=e($s['game_mode']??'Skirmish')?>" data-players="<?=(int)$s['players']?>" data-capacity="<?=(int)$s['capacity']?>" data-open-slots="<?=isset($s['player_slots'])?(int)$s['player_slots']:max(0,(int)$s['capacity']-(int)$s['players'])?>" data-started="<?=$s['started']?'1':'0'?>"><td><strong><?=e($s['name'])?></strong><span class="cell-sub"><?=e(map_title($s['map']))?> · <?=e($s['region']??'Unspecified')?> · <?=e($s['game_mode']??'Skirmish')?></span><span class="cell-sub">Engine <?=e(($s['version']??'')?:'not advertised')?> · verified map delivery</span><?php if(isset($s['player_slots'])):?><span class="cell-sub"><?=(int)$s['player_slots']?> player slots open · <?=(int)$s['spectators']?> watching · <?=(int)$s['bots']?> bots · <?=e(['Easy','Normal','Hard','Expert'][$s['difficulty']])?> · <?=(int)$s['speed_percent']?>% speed</span><?php else:?><span class="cell-sub">Player and spectator availability confirmed on connection</span><?php endif;?></td><td><span class="badge <?=$s['started']?'muted':($full?'muted':'online')?>"><i></i><?=$s['started']?'In battle':($full?'Full lobby':'Open lobby')?></span></td><td class="mono"><?=number($s['players'])?><span class="dim"> / <?=number($s['capacity'])?></span></td><td class="mono small"><?=e($s['host'])?>:<?=e($s['port'])?></td><td><button class="button button-small favorite-button" type="button" data-favorite="<?=e($s['id'])?>" aria-label="Toggle favorite server" aria-pressed="false">☆</button> <button class="button button-small join-button" data-id="<?=e($s['id'])?>" data-host="<?=e($s['host'])?>" data-port="<?=e($s['port'])?>" data-name="<?=e($s['name'])?>">Join </button> <a class="text-link small" href="/reports?kind=server&amp;target=<?=e($s['id'])?>">Report</a></td></tr><?php endforeach?></tbody></table></div><?php
}
function leaderboard_table(array $rows): void {
    if (!$rows) {empty_state('Your first battle starts the story.','Completed public matches will appear here. Create an account and join a public server to start your record.','/account','Create your account');return;}
    ?><div class="table-scroll"><table><thead><tr><th>Rank</th><th>Commander</th><th>Wins</th><th>Matches</th><th>Win rate</th><th>Units destroyed</th><th>Zones captured</th></tr></thead><tbody><?php foreach($rows as $i=>$r):?><tr><td class="rank <?=$i===0?'first':''?>"><?=sprintf('%02d',$i+1)?></td><td><a class="player-name" href="/players/<?=rawurlencode($r['username'])?>"><span class="avatar"><?=e(strtoupper(substr($r['username'],0,1)))?></span><?=e($r['username'])?></a></td><td class="accent mono"><?=number($r['wins'])?></td><td class="mono"><?=number($r['matches'])?></td><td class="mono"><?=$r['matches']?round(100*$r['wins']/$r['matches']):0?>%</td><td class="mono"><?=number($r['kills'])?></td><td class="mono"><?=number($r['captures'])?></td></tr><?php endforeach?></tbody></table></div><?php
}
function join_dialog(): void { ?><dialog id="join-dialog" aria-labelledby="join-title"><div class="dialog-heading"><span class="eyebrow">PUBLIC SERVER ACCESS</span><button class="icon-button close-dialog" aria-label="Close join dialog">×</button></div><h2 id="join-title">Join the battlefield.</h2><p id="join-description">Your ticket works once, on this server, for two minutes.</p><p id="join-feedback" role="status" aria-live="polite"></p><div id="join-commands" hidden><label for="join-platform">Your platform</label><select id="join-platform"><option value="unix">macOS / Linux</option><option value="windows">Windows PowerShell</option></select><pre><code id="join-command"></code></pre><button class="button copy-command">Copy command</button><p class="small dim">Replace the executable path with your local Zod game. Keep this ticket private. Get a fresh ticket for another connection.</p></div><a class="text-link" id="join-login" href="/account" hidden>Sign in or create an account</a></dialog><?php }
function render_page(string $path,ZodService $service): void {
    $profile=null;
    if (preg_match('~\A/players/([A-Za-z][A-Za-z0-9_]{2,23})\z~',$path,$match)) {$profile=$service->profile($match[1]);if(!$profile)fail(404,'This commander was not found.');$active='profile';}
    else {$active=match($path){'/'=>'home','/features'=>'features','/network'=>'network','/api'=>'api-browser','/api-browser'=>'api-browser','/servers'=>'servers','/leaderboard'=>'leaderboard','/statistics'=>'statistics','/downloads'=>'downloads','/account'=>'account','/community'=>'community','/creations'=>'creations','/server-presets'=>'server-presets','/match-history'=>'match-history','/server-console'=>'server-console','/server-rotation'=>'server-rotation','/my-servers'=>'my-servers','/server-auth'=>'server-auth','/admin'=>'admin','/reports'=>'reports','/connect'=>'connect','/guide'=>'guide','/credits'=>'credits',default=>fail(404,'This page was not found.')};}
    $me=$service->currentAccount();$token=csrf();page_header($active,$me);
    if($active==='server-presets')server_presets_page($service,$token);
    elseif($active==='match-history')match_history_page($service);
    elseif($active==='server-console')server_console_page($service,$token);
    elseif($active==='server-rotation')server_rotation_page($service,$token);
    elseif($active==='my-servers')owned_servers_page($service,$token);
    elseif($active==='server-auth')server_auth_page($service,$token);
    elseif($active==='admin')moderation_page($service,$token);
    elseif($active==='reports')report_page($service,$token);
    elseif ($active==='home') {
        $servers=$service->servers();$totals=$service->totals();$players=array_sum(array_column($servers,'players'));
        ?><section class="hero"><div class="shell hero-layout"><div class="hero-content"><div class="eyebrow"><span class="status-square"></span>CLASSIC RTS. MODERN MACHINES.</div><h1>Capture territory.<br><span>Command the battlefield.</span></h1><p>The real-time strategy you remember, rebuilt for today. Rally your robots, take the factories, and make every order count.</p><p class="small">A community fork of Zod Engine, the open-source remake of Z by The Bitmap Brothers. <a href="/credits">Meet the original creators</a></p><div class="button-row"><a class="button button-primary" href="/downloads">Get the game </a><a class="button button-ghost" href="/servers">Find a server </a></div><div class="platform-note"><span>WINDOWS</span><i></i><span>macOS</span><i></i><span>LINUX</span><span class="source-note">OPEN SOURCE / GPLv3</span></div></div></div></section><div class="shell live-strip"><div><span class="live-label"><i></i> NETWORK STATUS</span><strong><?=number(count($servers))?> <small>public servers</small></strong></div><div><span class="micro">ON THE FIELD</span><strong><?=number($players)?> <small>players online</small></strong></div><div><span class="micro">BATTLES RECORDED</span><strong><?=number($totals['matches'])?> <small>completed matches</small></strong></div><a href="/statistics" class="text-link">View network statistics</a></div><section class="shell section"><div class="section-heading"><div><span class="eyebrow">MULTIPLAYER / LIVE DIRECTORY</span><h2>Find your next battle.</h2></div><a class="text-link" href="/servers">All servers</a></div><div class="panel"><?php server_table(array_slice($servers,0,4));?></div><div class="section-note"><span class="tiny-square"></span>Public servers require a free Zod account. Private servers welcome guests.</div></section><section class="shell feature-preview"><div><span class="eyebrow">MORE WAYS TO PLAY &amp; CREATE</span><h2>A familiar game. Room to grow.</h2><p>Online multiplayer, a community server portal and expanded map and campaign editors for macOS, Windows and Linux.</p></div><a href="/features" class="button">Explore features</a></section><section class="shell section"><div class="section-heading"><div><span class="eyebrow">COMMANDER RECORDS</span><h2>Names on the board.</h2></div><a class="text-link" href="/leaderboard">Full leaderboard</a></div><div class="panel"><?php leaderboard_table($service->leaderboard(5));?></div></section><section class="shell callout"><div><span class="eyebrow">THE NEXT ORDER IS YOURS</span><h2>A classic worth commanding again.</h2><p>Start with a local battle. Bring your friends when you're ready.</p></div><a class="button button-primary" href="/downloads">Get started</a></section><?php
